const HEALK=['pb_1_3','gl_2_2','tb_9_4','pb_5_2','pb_6_2','pb_9_3','gl_8_1','tb_4_4','tb_12_4','gl_3_1','pb_2_2','pb_6_4','tb_6_4','pb_12_3','pb_7_4','gl_6_1','gl_4_1','gl_12_2'];
