    /* ---- conditions and selectors ---- */
    tWard(A,T,u,c){ return isWard(u,c.tgt); }, uWard(A,T,u,c){ return isWard(u,c.unit); }, isWardX(A,T,u,c){ return isWard(u,c.tgt); },
