    ow_3_1:[ {param:'kh.dur',add:R(0.5)} ],                                                                       // Long in the Kiln
    ow_3_2:[ {on:'out',ignoreArmor:R(0.02)} ],                                                                    // Glazer's Eye
    ow_4_3:[ {on:'teamHeal',if:{fn:'jarUnit'},more:R(0.03)}, {on:'healMe',if:{fn:'jarSelf'},more:R(0.03)} ],      // Jar Lid
