    fm_9_3:[ {param:'wl.nova',add:R(0.6)} ],                                                                        // Morning Chorus (needs Fourth Morning Nova)
    fm_8_2:[ {param:'wt.dmg',add:R(0.01)} ],                                                                        // Last Watchfire
