    sb_12_2:[ {param:'ch.h',add:R(0.03)} ],                                                                         // Whole Deep at Once (chHeal)
    sb_12_3:[ {param:'dw.all',add:R(0.006)} ],                                                                      // Drowning Weight (outK)
    sb_10_2:[ {on:'kit',skill:CH,opt:{radius:{addM:R(0.3)}}} ],                                                     // Pressure Wave
