    /* ---- OPEN EVERY DOOR ---- */
    kitOED(A,T,u,c){ const o=S(T); o.oRipe=new Set(); for(const [x,e] of (o.e0||[])) if(x.team!==u.team&&e>=RIPE) o.oRipe.add(x); },
