    tw_11_4:[ {param:'dr.ww',add:R(0.015)} ],                                                        // Woodland Ward (teamF)
    tw_12_2:[ {param:'rot.dur',add:R(0.4)} ],                                                        // Rotwood (rot)
    tw_12_3:[ {param:'bitter',add:R(0.04)} ],                                                        // Bitter Spring (bite)
