    fm_9_4:[ {param:'shaker',add:1} ],                                                                              // Worldshaker (slam, tremor)
    fm_10_1:[ {on:'hit',if:{auto:true,targetTeam:'enemy',stackMin:{peHeat:6}},do:[{fn:'fireFist'}]} ],             // Fire Fists
