      if(P.vent9) s.pyVent={x:f.x,y:f.y,R:f.R,raw:f.raw*hk,at:[0.8,2.4,4],t:0};
      if(P.crown){ A.acts(T,u,[{window:'pyCrown',dur:6},{window:'pyFree',dur:6,longest:true}],{u}); s.pyUhCd=0; T.fn.shimFull(A,T,u); }
