        if(thOn){ if(r.rot){ r.th=Math.min(TH_MAX,r.th+dt*rate); r.keep=keep; } else if(r.th>0){ if(r.keep>0) r.keep-=dt; else r.th=0; }
          if(z&&P.nbs) r.th=TH_MAX; }
