      if(P.shroud){ const al=E.units(); for(const a of al){ if(a.team!==u.team||a===u) continue; const inF=a.alive&&um.f.length&&!!fieldAt(T,a); if(inF) a._talShd=u; else if(a._talShd===u) delete a._talShd; } }
