    teamMore(A,T,u,t){ const P=T.P, r=recOf(T,t); let k=1; if(P.bt&&T.fn.isCor(A,T,t)) k*=1+P.bt; if(P.dt&&r&&Math.floor(r.th+1e-9)>=TH_MAX) k*=1+P.dt; if(P.sless&&r&&r.inZ) k*=1+P.sless; return k; },
